CREATE TABLE public.conversion_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_name text NOT NULL CHECK(event_name IN ('Purchase','Lead','AddToCart')), event_key text NOT NULL UNIQUE, payload jsonb NOT NULL DEFAULT '{}', ga4_status text NOT NULL DEFAULT 'pending', meta_status text NOT NULL DEFAULT 'pending', last_error text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.conversion_events TO authenticated; GRANT ALL ON public.conversion_events TO service_role;
ALTER TABLE public.conversion_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin conversion reads" ON public.conversion_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.capture_conversion_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='leads' THEN INSERT INTO public.conversion_events(event_name,event_key,payload) VALUES('Lead','lead:'||NEW.id,jsonb_build_object('lead_id',NEW.id,'source',NEW.source)) ON CONFLICT(event_key) DO NOTHING; ELSIF TG_TABLE_NAME='orders' AND NEW.payment_status::text='paid' AND OLD.payment_status::text<>'paid' THEN INSERT INTO public.conversion_events(event_name,event_key,payload) VALUES('Purchase','purchase:'||NEW.id,jsonb_build_object('order_id',NEW.id,'transaction_id',NEW.order_number,'value',NEW.total,'currency','INR')) ON CONFLICT(event_key) DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER capture_lead_conversion AFTER INSERT ON public.leads FOR EACH ROW EXECUTE FUNCTION public.capture_conversion_event();
CREATE TRIGGER capture_purchase_conversion AFTER UPDATE OF payment_status ON public.orders FOR EACH ROW EXECUTE FUNCTION public.capture_conversion_event();